from decimal import Decimal, InvalidOperation


def encode_amount(dollars: str) -> str:
    """Serialize a money amount to the ledger wire format: signed integer cents.

    Examples:
        '12.30'  -> '1230'
        '-0.07'  -> '-7'
        '0'      -> '0'

    The wire format is a base-10 integer number of cents with no decimal
    point, no leading zeros (other than a bare '0'), and an optional leading
    '-' for negative values. Positive values carry no '+'.
    """
    if not isinstance(dollars, str):
        raise ValueError(f"expected str, got {type(dollars).__name__}")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        value = Decimal(text)
    except InvalidOperation:
        raise ValueError(f"malformed amount: {dollars!r}")

    if not value.is_finite():
        raise ValueError(f"non-finite amount: {dollars!r}")

    cents = value.scaleb(2)
    if cents != cents.to_integral_value():
        raise ValueError(f"sub-cent precision not representable: {dollars!r}")

    return str(int(cents))

