def encode_amount(dollars: str) -> str:
    """Serialize a money amount to the ledger wire format: signed integer minor units (cents).

    The wire format for this ledger is the exact number of cents as a base-10
    integer string, e.g. '12.30' -> '1230', '-0.07' -> '-7', '0.00' -> '0'.
    No decimal point, no leading zeros (other than a lone '0'), and a leading
    '-' only for negative, non-zero amounts.
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        whole, _, frac = s.partition(".")
        if "." in frac:
            raise ValueError("too many decimal points")
    else:
        whole, frac = s, ""

    whole = whole or "0"
    if not whole.isdigit() or (frac and not frac.isdigit()):
        raise ValueError("malformed amount: %r" % (dollars,))

    # Normalize fractional part to exactly two digits (cents).
    if len(frac) > 2:
        raise ValueError("more than two fractional digits: %r" % (dollars,))
    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)
    if negative and cents != 0:
        cents = -cents

    return str(cents)
